@namespace sv_cc92bf63bc594ebdb0a6cc61eaa89984.Components.Pages.Chat

<div class="message-area">
    @if (ChannelName is not null)
    {
        <div class="message-area-header">
            <h4># @ChannelName</h4>
            <p class="channel-desc">@ChannelDescription</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @foreach (var message in Messages)
            {
                <MessageBubble Message="message"
                               ThreadSummary="GetThreadSummary(message.Id)"
                               OnThreadOpen="OnThreadOpen"
                               OnReactionAdded="OnReactionAdded" />
            }
        </div>

        <MessageInput Placeholder="Message #@ChannelName" ButtonText="Send" OnSend="OnMessageSend" />
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public string? ChannelName { get; set; }
    [Parameter] public string? ChannelDescription { get; set; }
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<Message> OnThreadOpen { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionAdded { get; set; }
    [Parameter] public EventCallback<string> OnMessageSend { get; set; }
    [Parameter] public EventCallback OnScrollToTop { get; set; }

    private ElementReference messageListRef;

    private ThreadSummary? GetThreadSummary(int messageId)
        => ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    private async Task HandleScroll()
    {
        // Scroll-to-top detection is handled via JS interop for precision,
        // but we trigger load on the event for simplicity here
        await OnScrollToTop.InvokeAsync();
    }
}

